import React, { Dispatch, FC, FormEvent, SetStateAction, useEffect, useState } from 'react';
import './ModalReminderForm.scss';
import { IReminder } from "../../../interfaces/reminderInterfaces";
import Modal from "../../common/Modal/Modal";
import Select from "../../common/Select/Select";

interface ModalReminderFormProps {
    reminder: IReminder;
    setReminder: (reminder: IReminder) => void;
    handleSubmit: (e: FormEvent) => void;
    headText: string;
    active: boolean;
    setActive: Dispatch<SetStateAction<boolean>>;
}

const ModalReminderForm: FC<ModalReminderFormProps> = ({ reminder, setReminder, handleSubmit, headText, active, setActive }) => {
    const [localReminder, setLocalReminder] = useState({ ...reminder, dueDate: reminder.dueDate.slice(0, 16) });

    useEffect(() => {
        setLocalReminder({ ...reminder, dueDate: reminder.dueDate.slice(0, 16) });
    }, [reminder]);

    return (
        <Modal headText={headText} active={active} setActive={setActive}>
            <form className='reminder-modal-form' onSubmit={handleSubmit}>
                <label htmlFor={"modal-title"}>Title</label>
                <input
                    type={"text"}
                    placeholder={"Title"}
                    name={"modal-title"}
                    value={localReminder.title}
                    onChange={(e) => setLocalReminder({ ...localReminder, title: e.target.value })}
                />
                <label htmlFor={"modal-description"}>Description</label>
                <textarea
                    placeholder={"Description"}
                    rows={5}
                    name={"modal-description"}
                    value={localReminder.description}
                    onChange={(e) => setLocalReminder({ ...localReminder, description: e.target.value })}
                ></textarea>
                <label htmlFor={"modal-price"}>Price</label>
                <input
                    type={"number"}
                    placeholder={"Price"}
                    min={0}
                    name={"modal-price"}
                    value={localReminder.price}
                    onChange={(e) => setLocalReminder({ ...localReminder, price: Number(e.target.value) })}
                />
                <label htmlFor={"modal-due-date"}>Due date</label>
                <input
                    type={"datetime-local"}
                    name={"modal-due-date"}
                    value={localReminder.dueDate}
                    onChange={(e) => setLocalReminder({ ...localReminder, dueDate: e.target.value })}
                />
                <Select
                    name={"Subject"}
                    values={["family", "health", "job", "education", "hobby", "others"]}
                    options={["Family", "Health", "Job", "Education", "Hobby", "Others"]}
                    value={localReminder.subject}
                    onChange={(e) => setLocalReminder({ ...localReminder, subject: e.target.value })}
                />
                <button className={'submit-modal'} type={'submit'}>Submit</button>
            </form>
        </Modal>
    );
};

export default ModalReminderForm;
